@page "/chat"
@layout ChatLayout
@using sv_051036244a4f40708d4a08c251ef5f3f.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<div class="chat-container">
    @* ─── LEFT SIDEBAR: Channel List ─── *@
    <div class="chat-sidebar">
        <div class="sidebar-header">
            <h5>Channels</h5>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </div>

    @* ─── MAIN MESSAGE AREA ─── *@
    <div class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h5># @_activeChannel.Name</h5>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="OnMainScrollAsync">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-header">
                                <span class="message-author">@msg.Author</span>
                                <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @* Reactions *@
                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in msg.Reactions)
                                    {
                                        <button class="reaction-badge" title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ReactAsync(msg.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @* Thread starter link *@
                            @if (GetThreadSummary(msg.Id) is { } thread)
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
                                    💬 @thread.ReplyCount @(thread.ReplyCount == 1 ? "reply" : "replies")
                                    — last @FormatRelativeTime(thread.LastReplyAt)
                                </button>
                            }

                            @* Hover action buttons *@
                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg)">💬 Reply</button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" title="Add reaction"
                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😀 React</button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _quickEmojis)
                                                {
                                                    <button class="emoji-option"
                                                            @onclick="() => ReactAsync(msg.Id, emoji)">@emoji</button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" rows="2"
                          placeholder="Message #@_activeChannel.Name"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="OnMainKeyDownAsync" />
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @* ─── RIGHT PANEL: Thread View ─── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <div class="thread-header">
                <h6>Thread</h6>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            <div class="thread-root-quote">
                <span class="message-author">@_threadRootMessage.Author</span>
                <span class="message-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                <div class="message-content">@_threadRootMessage.Content</div>
            </div>

            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-row">
                            <div class="message-header">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>

                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <button class="reaction-badge"
                                                title="@string.Join(", ", reaction.Users)"
                                                @onclick="() => ReactAsync(reply.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" rows="2"
                          placeholder="Reply…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDownAsync" />
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
                    Reply
                </button>
            </div>
        </div>
    }
</div>

@code {
    // ── Quick-reaction emoji palette ──
    private static readonly string[] _quickEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    // ── Channel state ──
    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;

    // ── Message state ──
    private List<Message>? _messages;
    private string _newMessageText = string.Empty;
    private const int PageSize = 30;
    private bool _loadingMore;
    private bool _allMessagesLoaded;

    // ── Thread state ──
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReplyText = string.Empty;

    // ── Thread summaries for the current channel (keyed by root message id) ──
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    // ── Hover / emoji picker state ──
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    // ── Channel selection ──
    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _allMessagesLoaded = false;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channel.Id);
        // Reflect zero unread locally
        var idx = _channels!.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
            _channels[idx] = channel with { UnreadCount = 0 };
    }

    // ── Pagination (scroll-to-top) ──
    private async Task OnMainScrollAsync()
    {
        // Triggered on every scroll; only act when we have messages and haven't loaded everything.
        if (_loadingMore || _allMessagesLoaded || _messages is null || _activeChannelId is null) return;

        // We cannot read scrollTop from C# without JS interop, so we use a
        // simple heuristic: request more messages whenever the scroll event fires
        // and the list is small enough that the user is likely near the top.
        // In a production app you would use JS interop for precise scroll position.
        _loadingMore = true;
        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        if (older.Count == 0)
        {
            _allMessagesLoaded = true;
        }
        else
        {
            _messages.InsertRange(0, older);
            BuildThreadSummaries();
        }
        _loadingMore = false;
    }

    // ── Send message ──
    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(sent);
        _newMessageText = string.Empty;
    }

    private async Task OnMainKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
            await SendMessageAsync();
    }

    // ── Reactions ──
    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Optimistic local update
        var msg = _messages?.FirstOrDefault(m => m.Id == messageId)
                  ?? _threadMessages?.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null && !existing.Users.Contains("You"))
                existing.Users.Add("You");
            else if (existing is null)
                msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Thread ──
    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
        _threadOpen = true;
        _threadReplyText = string.Empty;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootMessage.Id);
        _threadMessages ??= new();
        _threadMessages.Add(reply);
        _threadReplyText = string.Empty;

        // Update thread summary locally
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadMessages.Count,
            reply.SentAt);
    }

    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
            await SendThreadReplyAsync();
    }

    // ── Thread summary helpers ──
    private void BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        if (_messages is null) return;

        // A message is a "thread starter" if other messages reference it via ReplyToId.
        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt));
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        _threadSummaries.TryGetValue(messageId, out var summary);
        return summary;
    }

    // ── Formatting helpers ──
    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length <= 50 ? desc : desc[..47] + "…";
    }
}

